const DICTS: Record<Lang, Dict> = { pt, en, es, fr, de };
let current: Lang = "pt";

export const getLang = () => current;
export const decimalSep = () => (current === "en" ? "." : ",");
export const dateOrder = () => (current === "en" ? "MDY" : "DMY");

export function t(key: string, params?: Record<string, string | number>): string {
  let k = key;
  if (params && typeof params.n === "number") {
    const plural = `${key}_${params.n === 1 ? "one" : "other"}`;
    if (DICTS[current][plural] || pt[plural]) k = plural;
  }
  let s = DICTS[current][k] ?? pt[k] ?? key;
  if (params) for (const [p, v] of Object.entries(params)) s = s.split(`{${p}}`).join(String(v));
  return s;
}

export async function loadLang(): Promise<Lang> {
  const saved = (await storage.getItem("app_lang", "")) as string;
  if (saved && saved in DICTS) current = saved as Lang;
  else {
    const dev = getLocales()[0]?.languageCode ?? "en";
    current = (dev in DICTS ? dev : "en") as Lang;
  }
  return current;
}

export async function saveLang(l: Lang) {
  current = l;
  await storage.setItem("app_lang", l);
}
